let S=JSON.parse(localStorage.getItem(KEY)||'null')||seed();if(!S.time)S.time=seed().time;const save=()=>localStorage.setItem(KEY,JSON.stringify(S));save();
function resetData(){if(confirm('Reset all sample data?')){S=seed();save();route()}}
function logout(){WKAuth.logout();location.href='../login.html'}
function toast(t){const e=$('#toast');e.textContent=t;e.style.display='block';clearTimeout(e._t);e._t=setTimeout(()=>e.style.display='none',2600)}
