const hdr=(t,extra='')=>`<div class="top"><h1>${t}</h1><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">${extra}${SAMPLE}</div></div>`;
function route(){const r=(location.hash||'#dashboard').slice(1).split('/')[0];nav(r);$('#side').classList.remove('open');(V[r]||V.dashboard)();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);
function openD(html){$('#drawer').innerHTML='<button class="btn s" style="float:right" onclick="closeD()">Close ✕</button>'+html;$('#drawer').classList.add('open');$('#shade').classList.add('open')}
function closeD(){$('#drawer').classList.remove('open');$('#shade').classList.remove('open')}
